import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Task management","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/task-management/index.md","filePath":"master/services/project/task-management/index.md","lastUpdated":1792041590000}'),r={name:"master/services/project/task-management/index.md"};function n(i,e,l,h,d,g){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="task-management" tabindex="-1">Task management <a class="header-anchor" href="#task-management" aria-label="Permalink to &quot;Task management&quot;">​</a></h1><p>A task is one piece of work with a title, an owner, a deadline and a place in your workflow. Tasks usually belong to a project, and big tasks can be split into sub-tasks. This group shows you how to set up the workflow, create tasks, find them again and track the time spent.</p><blockquote><p><strong>In simple words:</strong> Tasks are the to-do items of a project. Stages show where each one is, and the State shows how it is going.</p></blockquote><p>Open <code>Project → Tasks</code> to see every task you are allowed to see.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task stages  ──►  Task  ──►  State  ──►  Sub-tasks  ──►  Time</span></span>
<span class="line"><span>(per project)    (create)   (progress)   (split work)   (rolls up)</span></span></code></pre></div><ol><li><strong>Add task stages to the project.</strong> A task cannot be saved until its project has at least one stage. See <a href="./task-stages-and-states.html">Task stages and states</a>.</li><li><strong>Create the task.</strong> Fill the title, assignees, deadline and allocated hours. See <a href="./create-task.html">Create a task</a>.</li><li><strong>Keep the State up to date.</strong> The State says whether work is in progress, approved or done.</li><li><strong>Split large work into sub-tasks.</strong> See <a href="./sub-tasks.html">Sub-tasks</a>.</li><li><strong>Log time.</strong> Hours logged on sub-tasks add up on the parent task. See <a href="./../../timesheets/log-time.html">Log time</a>.</li></ol><h2 id="running-example" tabindex="-1">Running example <a class="header-anchor" href="#running-example" aria-label="Permalink to &quot;Running example&quot;">​</a></h2><p>The guide follows the project <strong>Website Revamp</strong> for the customer <strong>Azure Interiors</strong>. Its task stages are <strong>New</strong>, <strong>In Progress</strong>, <strong>Review</strong> and <strong>Done</strong>. You will create the task <strong>Prepare launch announcement</strong> and a sub-task <strong>Draft email copy</strong> under it.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./create-task.html">Create a task</a></td><td>The form, starring a task, view, edit and archive</td></tr><tr><td><a href="./task-stages-and-states.html">Task stages and states</a></td><td>Stages versus States, and the five States</td></tr><tr><td><a href="./task-list-views-and-filters.html">Task list views and filters</a></td><td>Tabs, columns, grouping, filters and bulk actions</td></tr><tr><td><a href="./sub-tasks.html">Sub-tasks</a></td><td>Split a task and see time roll up</td></tr></tbody></table><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some fields only appear when a feature is on. Time fields need <strong>Enable Timesheets</strong>. The <strong>Milestone</strong> field needs <strong>Enable Milestones</strong>. See <a href="./../get-started/project-settings.html">Project settings</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../project-management/create-project.html">Create a project</a></li><li><a href="./../project-management/project-stages-and-milestones.html">Project stages and milestones</a></li><li><a href="./../configuration/tags.html">Tags</a></li><li><a href="./../../../getting-started/chatter.html">Chatter</a></li></ul>`,15)]))}const m=t(r,[["render",n]]);export{c as __pageData,m as default};
